typedef struct{unsigned inside,editing,id,row,draft,support,supportRow;}CampaignPartyUI200;
static CampaignPartyUI200 campaignPartyUI200;
static void campaign_party_ui_reset200(void){memset(&campaignPartyUI200,0,sizeof(campaignPartyUI200));}
static int party_roster_count200(void){Campaign200 c;if(!campaignRosterState200||campaign_load200(campaignRosterState200,&c)!=1)return 0;unsigned n=0;for(unsigned id=0;id<19;id++)n+=(c.recruits>>id)&1;return(int)n;}
static unsigned party_roster_id200(unsigned row){Campaign200 c;if(!campaignRosterState200||campaign_load200(campaignRosterState200,&c)!=1)return 255;for(unsigned id=0;id<19;id++)if(c.recruits&(1u<<id)){if(!row--)return id;}return 255;}
static int party_config_commit_ui200(Combat*g,const CampaignPartyConfig200*c){Campaign200 story;if(!campaignPartyState200||campaign_load200(campaignPartyState200,&story)!=1||!party_config_store200(campaignPartyState200,c,story.recruits)){combat_message(g,"Companion settings could not be saved. Nothing changed.");return 0;}campaignConfig200=*c;return 1;}
static const unsigned party_support_skills200[]={SKILL_HEAL,SKILL_BLESSING,SKILL_INCREASE_AGI,SKILL_KYRIE,185};
static void campaign_party_input200(Combat*g,unsigned pressed,int*choice){CampaignPartyUI200*u=&campaignPartyUI200;int n=party_roster_count200();if(u->inside){if(u->support){if(pressed&4){u->support=0;return;}if(pressed&1024)u->supportRow=(u->supportRow+4)%5;if(pressed&2048)u->supportRow=(u->supportRow+1)%5;if((pressed&2)&&campaign_player_support200(g,u->id,party_support_skills200[u->supportRow])){g->utilityMenu=0;*choice=0;campaign_party_ui_reset200();}return;}if(pressed&4){if(u->editing)u->editing=0;else u->inside=0;return;}if(u->editing){unsigned max=u->row==2?1:2;if((pressed&4096)&&u->draft)u->draft--;if((pressed&8192)&&u->draft<max)u->draft++;if(pressed&2){CampaignPartyConfig200 c=campaignConfig200;unsigned char*p=u->row==0?c.mode:u->row==1?c.priority:c.skills;p[u->id]=(unsigned char)u->draft;if(party_config_commit_ui200(g,&c))u->editing=0;}return;}if(pressed&8){u->support=1;u->supportRow=0;return;}if(pressed&16){if(campaign_player_recover200(g,u->id)){g->utilityMenu=0;*choice=0;campaign_party_ui_reset200();}return;}if(pressed&1024)u->row=(u->row+2)%3;if(pressed&2048)u->row=(u->row+1)%3;if(pressed&2){u->draft=u->row==0?campaignConfig200.mode[u->id]:u->row==1?campaignConfig200.priority[u->id]:campaignConfig200.skills[u->id];u->editing=1;}return;}if(pressed&4){g->utilityMenu=0;*choice=0;campaign_party_ui_reset200();return;}if(!n)return;if(!campaignPartyState200){combat_message(g,"Companion data could not be read.");return;}if((pressed&16)&&party_target_ok200(g,g->target)){campaignCommandTarget200=g->target;campaignCommandLife200=g->mobs[g->target].life;campaignCommandMap200=g->mapId;campaignCommandUntil200=g->time+10;for(unsigned k=0;k<campaignParty200.count;k++)campaignParty200.members[k].thinkAt=0;combat_message(g,"Companions: focus on your selected enemy.");}if(*choice<0||*choice>=n)*choice=0;if(pressed&1024)*choice=(*choice+n-1)%n;if(pressed&2048)*choice=(*choice+1)%n;unsigned id=party_roster_id200((unsigned)*choice);if(id>=19)return;if(pressed&2){u->inside=1;u->id=id;u->row=u->editing=0;}if(pressed&8){CampaignPartyConfig200 c=campaignConfig200;int found=-1,freeSlot=-1;for(unsigned i=0;i<3;i++){if(c.active[i]==id)found=(int)i;if(c.active[i]==255&&freeSlot<0)freeSlot=(int)i;}if(found>=0)c.active[found]=255;else if(freeSlot>=0)c.active[freeSlot]=(unsigned char)id;else{combat_message(g,"Three companions are active. Reserve one before adding another.");return;}party_config_commit_ui200(g,&c);}}
static const char*party_mode_name200(unsigned n){static const char*s[]={"Assist target","Defend party","Hold fire"};return n<3?s[n]:"?";}
static const char*party_priority_name200(unsigned id,unsigned n){return n==0?"Balanced":n==1?"Attack":id==COMP200_YUUFA?"Healing":"Conserve SP";}
static void party_ui_bar200(int x,int y,int width,unsigned value,unsigned maximum,unsigned color){hud_quad(x,y,width,10,PARTY_BG_X200,PARTY_BG_Y200,38,15);if(!maximum)return;int fill=(int)((uint64_t)value*(width-4)/maximum);if(fill>width-4)fill=width-4;if(fill>0)pb_fill(x+2,y+2,fill,6,color);}
static void campaign_party_draw200(const Combat*g,int choice){CampaignPartyUI200*u=&campaignPartyUI200;if(u->inside&&u->support){ui_panel(110,116,420,258,"Support companion",1,-1);ui_scaled(130,140,.9f,"%s",campaignCompanions200[u->id].name);for(unsigned i=0;i<5;i++){unsigned skill=party_support_skills200[i];int y=166+(int)i*26,rank=skill_rank(g,skill);ui_cell(121,y-3,398,24,u->supportRow==i);ui_scaled(130,y,.9f,"%s",skillDefs[skill].name);if(rank)ui_scaled(346,y,.85f,"Lv%d  %d SP",rank,skill_cost(g,skill));else ui_scaled(346,y,.85f,"Not learned");}pb_fill(122,300,396,28,0xffe9eff5);ui_scaled(130,305,.85f,"Uses your learned skill and normal casting rules.");ui_hint64(126,348,.85f,"UP/DOWN: skill   A: cast   B: settings");return;}if(u->inside){ui_panel(110,116,420,258,campaignCompanions200[u->id].name,1,-1);static const char*names[]={"Behaviour","Priority","Skills"};for(unsigned row=0;row<3;row++){int y=151+(int)row*45;ui_cell(121,y-3,398,35,u->row==row);ui_scaled(130,y,1,"%s",names[row]);unsigned value=u->editing&&u->row==row?u->draft:row==0?campaignConfig200.mode[u->id]:row==1?campaignConfig200.priority[u->id]:campaignConfig200.skills[u->id];const char*text=row==0?party_mode_name200(value):row==1?party_priority_name200(u->id,value):value?"ON":"OFF";ui_fit47(278,y,222,1,text);if(u->editing&&u->row==row){unsigned max=row==2?1:2;if(value)ui_option_triangle62(260,y+5,0);if(value<max)ui_option_triangle62(506,y+5,1);}}unsigned selected=u->editing?u->draft:u->row==0?campaignConfig200.mode[u->id]:u->row==1?campaignConfig200.priority[u->id]:campaignConfig200.skills[u->id];const char*help;if(u->row==0)help=selected==0?"Assist your selected target, or enemies threatening the party.":selected==1?"Defend the party. Ignore enemies that are not threatening it.":"Hold attacks. Healing can still be used when Skills is ON.";else if(u->row==1){if(u->id==COMP200_YUUFA)help=selected==0?"Balance healing and attacks. Heal below 75% HP.":selected==1?"Focus on attacks. Heal emergencies below 50% HP.":"Focus on healing. Restore injured allies below 90% HP.";else help=selected==0?"Use Bash periodically between normal sword attacks.":selected==1?"Use Bash more often while SP permits.":"Use normal sword attacks and save SP.";}else help=selected?"Use this companion's learned skills automatically.":u->id==COMP200_YUUFA?"Follow without casting healing or offensive spells.":"Disable automatic skills. Normal sword attacks continue.";pb_fill(122,286,396,39,0xffe9eff5);char lines[8][96];int count=ui_wrap(help,lines,380,.85f);for(int n=0;n<count&&n<2;n++)ui_scaled(130,290+n*14,.85f,"%s",lines[n]);ui_hint64(126,332,.85f,u->editing?"LEFT/RIGHT: value   A: save   B: cancel":"A: edit   X: support skills   B: roster");if(!u->editing){const CampaignFollower200*member=party_member200(u->id);if(member&&skill_rank(g,member->hp?SKILL_HEAL:185))ui_hint64(126,352,.85f,member->hp?"Y: heal companion":"Y: revive companion");}return;}
 int count=party_roster_count200();if(count&&!campaignPartyState200){ui_panel(110,116,420,120,"Companions",1,-1);ui_scaled(126,151,1,"Companion data could not be read.");ui_hint64(126,204,.85f,"B: close");return;}int rows=count<3?count:3,height=rows?100+rows*76:110,y=78;ui_panel(110,y,420,height,"Companions",1,-1);if(!rows){ui_scaled(126,y+35,1,"No companions have joined your journey.");ui_hint64(126,y+height-25,.9f,"B: close");return;}hud_quad(126,y+27,21,10,PARTY_CROWN_X200,PARTY_ART_Y200,21,10);ui_scaled(154,y+24,.9f,"Your travelling party");int first=choice/3*3;for(int row=0;row<rows&&first+row<count;row++){unsigned id=party_roster_id200((unsigned)(first+row));int top=y+48+row*76;ui_cell(120,top-3,400,70,choice==first+row);CampaignFollower200*m=party_member200(id);int active=-1;for(unsigned k=0;k<3;k++)if(campaignConfig200.active[k]==id)active=(int)k;unsigned icon=id==COMP200_ROAN?PARTY_SWORD_X200:PARTY_ACO_X200;hud_quad(127,top,25,25,icon,PARTY_ART_Y200,25,25);ui_scaled(159,top,1,"%s",campaignCompanions200[id].name);ui_scaled(371,top,.85f,active<0?"Reserve":"Active %d",active+1);if(m&&m->initialized){ui_fit47(159,top+20,137,.85f,"HP");ui_scaled(182,top+20,.85f,"%u/%u",m->hp,m->maxHP);party_ui_bar200(309,top+20,201,m->hp,m->maxHP,0xff52c879);ui_scaled(159,top+35,.85f,"SP %u/%u",m->sp,m->maxSP);party_ui_bar200(309,top+35,201,m->sp,m->maxSP,0xff60a8e7);ui_scaled(159,top+50,.8f,"Lv %u - %s",m->level,!m->hp?"Defeated":job_name(m->job));}else ui_scaled(159,top+25,.9f,"%s path",job_name(campaignCompanions200[id].career));}ui_hint64(126,y+height-35,.8f,"A: settings   X: active/reserve   B: close");ui_hint64(126,y+height-18,.8f,"Y: focus selected enemy");(void)g;}
#endif
